<div class="admin-page-heading"><div><h1>บุคลากรกองประชาสัมพันธ์</h1><p>จัดการข้อมูลที่ได้รับอนุญาตให้เผยแพร่ แยกจากบัญชีผู้ใช้ระบบ</p></div><a class="button secondary" href="/personnel" target="_blank" rel="noopener">ดูหน้าบุคลากร ↗</a></div><?php if($error): ?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif ?><div class="management-grid"><section class="admin-panel form-panel"><h2><?= $edit?'แก้ไขข้อมูล':'เพิ่มบุคลากร' ?></h2><form method="post" data-unsaved><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>ชื่อ–นามสกุล *<input name="name" value="<?= e($edit['name']??'') ?>" maxlength="250" required></label><label>ตำแหน่ง *<input name="position" value="<?= e($edit['position']??'') ?>" maxlength="250" required></label><label>กลุ่มงาน<input name="department" value="<?= e($edit['department']??'') ?>" maxlength="250"></label><label>รูปบุคลากร<select name="photo_id"><option value="">ไม่มีรูป / ใช้ภาพแทน</option><?php foreach($images as $file): ?><option value="<?= $file['id'] ?>" <?= (int)($edit['photo_id']??0)===(int)$file['id']?'selected':'' ?>><?= e($file['name']) ?></option><?php endforeach ?></select></label><label>ลำดับ<input type="number" name="sort_order" value="<?= (int)($edit['sort_order']??0) ?>"></label><label class="checkbox"><input type="checkbox" name="published" <?= !empty($edit['published'])?'checked':'' ?>> เผยแพร่ข้อมูลบุคลากร</label><div class="button-row"><button class="button">บันทึก</button><?php if($edit): ?><a class="button secondary" href="/admin/personnel">ยกเลิก</a><?php endif ?></div></form></section><section class="admin-panel"><div class="panel-heading"><h2>รายชื่อบุคลากร</h2><span><?= count($people) ?> รายการ</span></div><?php if(!$people): ?><div class="empty-state"><h3>ยังไม่มีข้อมูลบุคลากร</h3><p>เพิ่มชื่อและตำแหน่งที่ได้รับการยืนยันแล้ว</p></div><?php endif ?><div class="person-list"><?php foreach($people as $p): ?><article><img src="<?= e(image_url($p['photo_id']?(int)$p['photo_id']:null,'/assets/person.svg')) ?>" alt=""><div><strong><?= e($p['name']) ?></strong><p><?= e($p['position']) ?></p><small>ลำดับ <?= $p['sort_order'] ?> · <?= $p['published']?'เผยแพร่':'ร่าง' ?></small></div><a class="text-link" href="/admin/personnel?edit=<?= $p['id'] ?>">แก้ไข</a><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="text-button destructive" name="action" value="delete" data-confirm="ลบข้อมูลบุคลากรนี้?">ลบ</button></form></article><?php endforeach ?></div></section></div>
